import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] v = new int[10];
        for (int i=0; i<k; i++) {
            v[scanner.nextInt()] = 1;
        }
        int[] resultPoly = {1};
        int power = n/2;
        while (power > 0) {
            if ((power & 1) == 1) {
                resultPoly = polyMultiply(resultPoly, v, 998244353);
            }
            v = polyMultiply(v, v, 998244353);
            power >>= 1;
        }
        long total = 0;
        for (int val : resultPoly) {
            total = (total + (long) val * val) % 998244353;
        }
        System.out.println(total);
    }

    static int[] polyMultiply(int[] a, int[] b, int mod) {
        int n = Math.max(2, Integer.highestOneBit(a.length + b.length - 1) << 1);
        double[] A = new double[n];
        double[] B = new double[n];
        for (int i=0; i<a.length; i++) {
            int x = ((a[i] % mod) + mod) % mod;
            A[i] = x & ((1 << 15) - 1);
            A[i] += (x >> 15) * 1e-6;
        }
        for (int i=0; i<b.length; i++) {
            int x = ((b[i] % mod) + mod) % mod;
            B[i] = x & ((1 << 15) - 1);
            B[i] += (x >> 15) * 1e-6;
        }
        fftAlgo(A, false);
        fftAlgo(B, false);
        double[] FA = new double[n];
        double[] FB = new double[n];
        for (int i=0; i<n; i++) {
            int j = (n - i) & (n - 1);
            double aReal = (A[i] + A[j]) * 0.5;
            double aImag = (A[i] - A[j]) * 0.5;
            double bReal = (B[i] + B[j]) * 0.5;
            double bImag = (B[i] - B[j]) * 0.5;
            FA[i] = aReal * bReal - aImag * bImag;
            FB[i] = aReal * bImag + aImag * bReal;
        }
        fftAlgo(FA, true);
        fftAlgo(FB, true);
        int[] res = new int[a.length+b.length-1];
        for (int i=0; i<res.length; i++) {
            long aa = Math.round(FA[i]);
            long bb = Math.round(FB[i]);
            long val = (aa + ((bb % mod) << 15)) % mod;
            res[i] = (int) val;
        }
        return res;
    }

    static void fftAlgo(double[] a, boolean invert) {
        int n = a.length;
        for (int i=1, j=0; i<n; i++) {
            int bitmask = n >> 1;
            for (; (j & bitmask) != 0; bitmask >>= 1) {
                j &= ~bitmask;
            }
            j |= bitmask;
            if (i < j) {
                double tmp = a[i];
                a[i]= a[j];
                a[j]= tmp;
            }
        }
        for (int len=2; len<=n; len <<=1) {
            double angle = 2*Math.PI / len * (invert ? -1 : 1);
            double wlenCos = Math.cos(angle);
            double wlenSin = Math.sin(angle);
            for (int i=0; i<n; i+=len) {
                double wCos=1, wSin=0;
                for (int j=0; j<len/2; j++) {
                    double u= a[i+j], v= a[i+j+len/2]*wCos + a[i+j+len/2]*wSin;
                    a[i+j]= u+v;
                    a[i+j+len/2]= u-v;
                    double tempW = wCos * wlenCos - wSin * wlenSin;
                    wSin= wSin*wlenCos + wCos*wlenSin;
                    wCos= tempW;
                }
            }
        }
        if (invert) {
            for (int i=0; i<n; i++) {
                a[i] /= n;
            }
        }
    }
}
